const today=()=>day(0);
const fd=s=>s?new Date(s.length<11?s+'T00:00':s).toLocaleDateString(undefined,{day:'numeric',month:'short',year:'numeric'}):'';
const ft=s=>new Date(s).toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit'});
let S,me=null,F={},K='',editing=null,preCat=null,lastView='';
function load(){try{S=JSON.parse(localStorage.getItem(LS))}catch(e){S=null}try{me=localStorage.getItem(SK)}catch(e){me=null}}
function save(){try{localStorage.setItem(LS,JSON.stringify(S));return true}catch(e){toast('Browser storage is full. Remove images or old posts.','err');return false}}
function setSess(v){me=v;try{v?localStorage.setItem(SK,v):localStorage.removeItem(SK)}catch(e){}}
async function hash(pw,salt){const b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(salt+pw));return[...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('')}
const user=()=>S.users.find(u=>u.id===me)||null,isAdm=()=>user()?.role==='admin',uName=id=>S.users.find(u=>u.id===id)?.name||'Former member';
const can=p=>{const u=user();return !!u&&(u.id===p.author||u.role==='admin')};
